cases.bad:
// Layer 1 (detector): only post when tracks exist
if (tracks.length > 0) postMessage({ type: 'DETECTED', tracks });
// Layer 2 (background): early return on 0 — no clear, no broadcast
if (subtitles.length === 0) return { success: true };
// Layer 3 (overlay): only toast on null, never clearCues
if (!target && !native) showToast('No subtitles');
// Composed: 0 tracks → no post → no clear → no clearCues → stale overlay

cases.good:
// Layer 1: post on EVERY detect incl. 0 tracks
postMessage({ type: 'DETECTED', tracks }); // 0 is a valid result
// Layer 2: 0-tracks path clears tab + broadcasts empty update + sends null AUTO_LOAD
clearTab(tabId); broadcastMediaUpdate([]); sendAutoLoad(tabId, null);
// Layer 3: null target+native calls clearCues + resets offset + empty nav cluster
controller.clearCues(); offsetController.reset(); updateNavCluster([]);
